     1→module protocol::liquidity_mining_reward_manager;
     2→
     3→// === Imports ===
     4→use std::type_name::{ Self, TypeName };
     5→
     6→use sui::balance::Balance;
     7→use sui::clock::Clock;
     8→use sui::bag::{Self, Bag};
     9→use sui::table::{Self, Table};
    10→
    11→use math::float::{Self, Decimal};
    12→use protocol::error;
    13→
    14→// === Constants ===
    15→const MAX_REWARDS: u64 = 50;
    16→const MIN_REWARD_PERIOD_MS: u64 = 3_600_000;
    17→
    18→// === Structs ===
    19→public struct PoolRewardManager has key, store{
    20→    id: UID,
    21→    total_shares: u64,
    22→    pool_rewards: vector<Option<PoolReward>>,
    23→    last_update_time_ms: u64,
    24→    obligation_reward_managers: Table<ID, ObligationRewardManager>
    25→}
    26→
    27→public struct PoolReward has key, store {
    28→    id: UID,
    29→    pool_reward_manager_id: ID,
    30→    coin_type: TypeName,
    31→    start_time_ms: u64,
    32→    end_time_ms: u64,
    33→    total_rewards: u64,
    34→    allocated_rewards: Decimal,
    35→    cumulative_rewards_per_share: Decimal,
    36→    num_obligation_reward_managers: u64,
    37→    additional_fields: Bag, 
    38→}
    39→
    40→// dynamic field key 
    41→public struct RewardBalance<phantom CoinType> has copy, drop, store {}
    42→
    43→public struct ObligationRewardManager has store { 
    44→    share: u64,
    45→    rewards: vector<Option<ObligationReward>>,
    46→    last_update_time_ms: u64,
    47→}
    48→
    49→public struct ObligationReward has store {
    50→    pool_reward_id: ID,
    51→    earned_rewards: Decimal,
    52→    cumulative_rewards_per_share: Decimal,
    53→}
    54→
    55→// === Public-View Fucntions ===
    56→public fun shares(obligation_reward_manager: &ObligationRewardManager): u64 {
    57→    obligation_reward_manager.share
    58→}
    59→
    60→public fun last_update_time_ms(obligation_reward_manager: &ObligationRewardManager): u64 {
    61→    obligation_reward_manager.last_update_time_ms
    62→}
    63→
    64→public fun pool_reward_id(pool_reward_manager: &PoolRewardManager, index: u64): ID {
    65→    let optional_pool_reward = pool_reward_manager.pool_rewards.borrow(index);
    66→    let pool_reward = option::borrow(optional_pool_reward);
    67→    object::id(pool_reward)
    68→}
    69→
    70→public fun pool_reward(
    71→    pool_reward_manager: &PoolRewardManager,
    72→    index: u64,
    73→): &Option<PoolReward> {
    74→   pool_reward_manager.pool_rewards.borrow( index)
    75→}
    76→
    77→public fun total_shares(
    78→    pool_reward_manager: &PoolRewardManager,
    79→): u64{
    80→    pool_reward_manager.total_shares
    81→}
    82→
    83→public fun end_time_ms(pool_reward: &PoolReward): u64 {
    84→    pool_reward.end_time_ms
    85→}
    86→
    87→// === Public(Package) Functions ===
    88→public(package) fun borrow_obligation_reward_managers(
    89→    pool_reward_manager: &PoolRewardManager,
    90→): &Table<ID, ObligationRewardManager>{
    91→    &pool_reward_manager.obligation_reward_managers
    92→}
    93→
    94→public(package) fun new_pool_reward_manager(
    95→    ctx: &mut TxContext,
    96→): PoolRewardManager{
    97→    PoolRewardManager{
    98→        id: object::new(ctx),
    99→        total_shares: 0,
   100→        pool_rewards: vector::empty(),
   101→        last_update_time_ms: 0,
   102→        obligation_reward_managers: table::new<ID, ObligationRewardManager>(ctx),
   103→    }
   104→}
   105→
   106→public(package) fun close_pool_reward<CoinType>(
   107→    pool_reward_manager: &mut PoolRewardManager,
   108→    index: u64,
   109→    clock: &Clock
   110→): Balance<CoinType>{
   111→    let optional_pool_reward = pool_reward_manager.pool_rewards.borrow_mut(index);
   112→    let PoolReward{
   113→        id,
   114→        pool_reward_manager_id: _,
   115→        coin_type: _,
   116→        start_time_ms: _,
   117→        end_time_ms,
   118→        total_rewards: _,
   119→        allocated_rewards: _,
   120→        cumulative_rewards_per_share: _,
   121→        num_obligation_reward_managers,
   122→        mut additional_fields,
   123→    } = optional_pool_reward.extract();
   124→
   125→    object::delete(id);
   126→
   127→    let cur_time_ms = clock.timestamp_ms();
   128→
   129→    assert!(cur_time_ms >= end_time_ms, error::liquidity_mining_pool_reward_period_not_over());
   130→    assert!(num_obligation_reward_managers == 0, error::liquidity_mining_not_all_rewards_claimed());
   131→
   132→    let reward_balance = additional_fields.remove<RewardBalance<CoinType>, Balance<CoinType>>(RewardBalance<CoinType>{});
   133→    additional_fields.destroy_empty();
   134→    
   135→    reward_balance
   136→}   
   137→
   138→public(package) fun cancel_pool_reward<CoinType>(
   139→    pool_reward_manager: &mut PoolRewardManager,
   140→    index: u64,
   141→    clock: &Clock,
   142→): Balance<CoinType>{
   143→    update_pool_reward_manager(pool_reward_manager, clock);
   144→    
   145→    let pool_reward = pool_reward_manager.pool_rewards.borrow_mut(index).borrow_mut();
   146→    let cur_time_ms = clock.timestamp_ms();
   147→    
   148→    let unallocated_rewards = 
   149→        float::from(pool_reward.total_rewards).sub(
   150→        pool_reward.allocated_rewards
   151→        ).floor();
   152→    
   153→    pool_reward.end_time_ms = cur_time_ms;
   154→    pool_reward.total_rewards = 0;
   155→
   156→    let reward_balance = pool_reward.additional_fields.borrow_mut<RewardBalance<CoinType>, Balance<CoinType>>(RewardBalance<CoinType>{});
   157→
   158→    reward_balance.split(unallocated_rewards)
   159→}
   160→
   161→public(package) fun add_pool_reward<CoinType>(
   162→    pool_reward_manager: &mut PoolRewardManager,
   163→    rewards: Balance<CoinType>,
   164→    start_time_ms: u64,
   165→    end_time_ms: u64,
   166→    clock: &Clock,
   167→    ctx: &mut TxContext
   168→){
   169→    assert!(start_time_ms >= clock.timestamp_ms(), error::liquidity_mining_invalid_start_time());
   170→    assert!(end_time_ms - start_time_ms >= MIN_REWARD_PERIOD_MS, error::liquidity_mining_invalid_time());
   171→
   172→    let pool_reward = PoolReward {
   173→        id: object::new(ctx),
   174→        pool_reward_manager_id: object::id(pool_reward_manager),
   175→        coin_type: type_name::with_defining_ids<CoinType>(),
   176→        start_time_ms,
   177→        end_time_ms,
   178→        total_rewards: rewards.value(),
   179→        allocated_rewards: float::from(0),
   180→        cumulative_rewards_per_share: float::from(0),
   181→        num_obligation_reward_managers: 0,
   182→        additional_fields: {
   183→            let mut bag = bag::new(ctx);
   184→            bag.add(RewardBalance<CoinType>{}, rewards);
   185→            bag
   186→        },
   187→    };
   188→
   189→    let i = find_available_index(pool_reward_manager);
   190→    assert!(i < MAX_REWARDS, error::liquidity_mining_max_concurrent_pool_rewards_violated());
   191→    
   192→    let optional_pool_reward = pool_reward_manager.pool_rewards.borrow_mut(i);
   193→    optional_pool_reward.fill(pool_reward);
   194→}
   195→
   196→public(package) fun new_obligation_reward_manager(
   197→    pool_reward_manager: &mut PoolRewardManager,
   198→    obligation_id: ID,
   199→    clock: &Clock,
   200→){
   201→    let obligation_reward_manager = ObligationRewardManager{
   202→        share: 0,
   203→        rewards: vector::empty(),
   204→        last_update_time_ms: clock.timestamp_ms(),
   205→    };
   206→
   207→    pool_reward_manager.obligation_reward_managers.add(obligation_id, obligation_reward_manager);
   208→    update_obligation_reward_manager(pool_reward_manager, obligation_id, clock, true);
   209→}
