module protocol::liquidity_mining;

use std::type_name::{Self, TypeName};
use sui::clock::Clock;
use sui::coin::Coin;
use sui::event::emit;

use protocol::market::Market;
use protocol::obligation::ObligationOwnerCap;

use protocol::app::ProtocolApp;

public struct RewardClaimedEvent has copy, drop {
    who: address,

    market: TypeName,
    obligation: ID,

    coin_type: TypeName,
    reward_coin_type: TypeName,

    reward_amount: u64,

    time: u64,
}


public fun claim_reward_as_coin<MarketType, CoinType, RewardCoinType>(
    app: &ProtocolApp,
    market: &mut Market<MarketType>,
    obligation_owner_cap: &ObligationOwnerCap,

    reward_type: u8,
    reward_index: u64,

    clock: &Clock,
    ctx: &mut TxContext,
): Coin<RewardCoinType>{
    app.validate_market<MarketType>(market);
    app.ensure_version_matches();

    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());

    let miner = market.borrow_liquidity_mining_mut<MarketType>();
    let claimed_reward = miner.claim_rewards<MarketType, CoinType, RewardCoinType>(
        reward_type,
        obligation_owner_cap.id(),
        clock,
        reward_index
    );

    emit(RewardClaimedEvent {
        who: ctx.sender(),
        market: type_name::with_defining_ids<MarketType>(),
        obligation: obligation_owner_cap.id(),
        coin_type: type_name::with_defining_ids<CoinType>(),
        reward_coin_type: type_name::with_defining_ids<RewardCoinType>(),
        reward_amount: claimed_reward.value(),
        time: clock.timestamp_ms() / 1000,
    });
    claimed_reward.into_coin(ctx)
}

#[allow(lint(self_transfer))]
public fun claim_reward<MarketType, CoinType, RewardCoinType>(
    app: &ProtocolApp,
    market: &mut Market<MarketType>,
    obligation_owner_cap: &ObligationOwnerCap,

    reward_type: u8,
    reward_index: u64,

    clock: &Clock,
    ctx: &mut TxContext,
) {
    let claimed_reward = claim_reward_as_coin<MarketType, CoinType, RewardCoinType>(
        app, market, obligation_owner_cap, reward_type, reward_index, clock, ctx
    );
    transfer::public_transfer(claimed_reward, ctx.sender());
}

